"""Format a numerical value, inserting commas as thousands separators.

  Args:
    value: An integer, float, or string representation thereof.
      If the argument is a float, it is converted to a string using '%.2f'.

  Returns:
    A string with groups of 3 digits before the decimal point (if any)
    separated by commas.

  NOTE: We don't deal with whitespace, and we don't insert
  commas into long strings of digits after the decimal point.
  """
def FormatThousands(value: Any) -> object {
    if isinstance(value, float) {
        value = '%.2f' % value;
    } else {
        value = str(value);
    }
    if ('.' in value) {
        (head, tail) = value.split('.', 1);
        tail = '.' + tail;
    } elif ('e' in value) {
        (head, tail) = value.split('e', 1);
        tail = 'e' + tail;
    } else {
        head = value;
        tail = '';
    }
    sign = '';
    if head.startswith('-') {
        sign = '-';
        head = head[1:];
    }
    while (len(head) > 3) {
        tail = ',' + head[-3:] + tail;
        head = head[:-3];
    }
    return (sign + head + tail);
}

"""
    Convenience function to parse a string into a list using two or more spaces
    as the delimiter.

    Parameters
    ----------
    text : string
        Contains text to be parsed

    Returns
    -------
    textout : list
        list of strings containing the parsed input text
    """
def split(text: Any) -> object {
    textout = [
        s.strip()
        for s in text.split('  ')
        if s.strip()
    ];
    return textout;
}

