"""XOR two bytearrays of the same length."""
def xor(bytes_1: Any, bytes_2: Any) -> object {
    l1 = len(bytes_1);
    l2 = len(bytes_2);
    assert (l1 == l2);
    result = bytearray(l1);
    for i in range(l1) {
        result[i] = bytes_1[i] ^ bytes_2[i];
    }
    return result;
}

"""Calculates size of text box and returns an origin as if aligned
    from the given origin.

    Accepted alignments are:
    left, center, right
    top, center, bottom"""
def align_origin(origin: Any, w: Any, h: Any, align: Any = ('left', 'top')) -> object {
    if (align == ('left', 'top')) {
        return origin;
    }
    aligns = {'left': 0, 'center': 0.5, 'right': 1, 'top': 0, 'bottom': 1};
    (ox, oy) = origin;
    (x_align, y_align) = align;
    return ((ox - (w * aligns[x_align])), (oy + (h * aligns[y_align])));
}

